previewCss:
.darma-loader-darma-b16-periscope-scan { --accent: var(--loader-color, #0891b2); --accent-2: var(--loader-secondary-color, #a5f3fc); width: var(--loader-size, 118px); height: calc(var(--loader-size, 118px) * .8); position: relative; overflow: hidden; border-radius: 8px; }
.darma-loader-darma-b16-periscope-scan .darma-loader-darma-b16-periscope-scan__sea { position: absolute; left: 0; right: 0; bottom: 0; height: 46%; background: linear-gradient(color-mix(in srgb, var(--accent) 40%, transparent), color-mix(in srgb, var(--accent) 12%, transparent)); }
.darma-loader-darma-b16-periscope-scan .darma-loader-darma-b16-periscope-scan__rig { position: absolute; left: 0; right: 0; bottom: 46%; height: 54%; animation: darma-loader-darma-b16-periscope-scan-peri-rise calc(var(--loader-speed, 1s) * 4) ease-in-out infinite; }
.darma-loader-darma-b16-periscope-scan .darma-loader-darma-b16-periscope-scan__tube { position: absolute; left: 47%; bottom: 0; width: 6%; height: 62%; border-radius: 3px 3px 0 0; background: linear-gradient(var(--accent-2), var(--accent)); }
.darma-loader-darma-b16-periscope-scan .darma-loader-darma-b16-periscope-scan__head { position: absolute; left: 40%; bottom: 56%; width: 20%; height: 12%; border-radius: 4px; background: var(--accent); transform-origin: 50% 100%; animation: darma-loader-darma-b16-periscope-scan-peri-turn calc(var(--loader-speed, 1s) * 2) ease-in-out infinite alternate; }
.darma-loader-darma-b16-periscope-scan .darma-loader-darma-b16-periscope-scan__beam { position: absolute; left: 20%; bottom: 40%; width: 60%; height: 34%; background: conic-gradient(from -30deg at 50% 100%, transparent 0deg, color-mix(in srgb, var(--accent-2) 60%, transparent) 20deg, transparent 40deg); transform-origin: 50% 100%; animation: darma-loader-darma-b16-periscope-scan-peri-turn calc(var(--loader-speed, 1s) * 2) ease-in-out infinite alternate; }
@keyframes darma-loader-darma-b16-periscope-scan-peri-rise { 0%, 100% { transform: translateY(46%); } 26%, 74% { transform: translateY(0); } }
@keyframes darma-loader-darma-b16-periscope-scan-peri-turn { from { transform: rotate(-40deg); } to { transform: rotate(40deg); } }

